",\"    writer = csv.writer(\",\"        stream, delimiter=delim, quotechar=quote, lineterminator=terminator,\",\"        quoting=csv.QUOTE_ALL if quote_all else csv.QUOTE_MINIMAL,\",\"        escapechar=escape, doublequote=double_quote)\",\"    for row in rows:\",\"        writer.writerow(row)\",\"    return encode_text(stream.getvalue())\",\"\",\"\",\"def write_bytes(data, path=None):\",\"    if path is None or path == \\\"-\\\":\",\"        sys.stdout.buffer.write(data)\",\"        sys.stdout.buffer.flush()\",\"    else:\",\"        with open(path, \\\"wb\\\") as handle:\",\"            handle.write(data)\",\"\",\"\",\"def command_input(positional, minimum=0, maximum=1):\",\"    if len(positional) < minimum or len(positional) > maximum:\",\"        raise XsvError(\\\"Invalid arguments.\\\")\",\"    return positional[-1] if positional else None\",\"\",\"\",\"def split_selector(raw):\",\"    pieces = []\",\"    current = []\",\"    quoted = False\",\"    i = 0\",\"    while i < len(raw):\",\"        char = raw[i]\",\"        if char == '\\\"':\",\"            if quoted and i + 1 < len(raw) and raw[i + 1] == '\\\"':\",\"                current.append('\\\"')\",\"                i += 2\",\"                continue\",\"            quoted = not quoted\",\"            current.append(char)\",\"        elif char == \\\",\\\" and not quoted:\",\"            pieces.append(\\\"\\\".join(current))\",\"            current = []\",\"        else:\",\"            current.append(char)\",\"        i += 1\",\"    if quoted:\",\"        raise XsvError(\\\"Unclosed quote in selector.\\\")\",\"    pieces.append(\\\"\\\".join(current))\",\"    return pieces\",\"\",\"\",\"def selector_hyphen(token):\",\"    quoted = False\",\"    for i, char in enumerate(token):\",\"        if char == '\\\"':\",\"            quoted = not quoted\",\"        elif char == \\\"-\\\" and not quoted:\",\"            return token[:i], token[i + 1:]\",\"    return None\",\"\",\"\",\"def parse_one_selector(token)