   for token in split_selector(raw):\",\"            span = selector_hyphen(token)\",\"            if span is None:\",\"                indices.append(one_index(parse_one_selector(token), headers, use_names))\",\"                continue\",\"            left, right = span\",\"            first = one_index(parse_one_selector(left) if left else None,\",\"                              headers, use_names, \\\"start\\\")\",\"            last = one_index(parse_one_selector(right) if right else None,\",\"                             headers, use_names, \\\"end\\\")\",\"            step = 1 if first <= last else -1\",\"            indices.extend(range(first, last + step, step))\",\"    if invert:\",\"        omitted = set(indices)\",\"        return [i for i in range(len(headers)) if i not in omitted]\",\"    return indices\",\"\",\"\",\"def selected(row, indices):\",\"    return [row[i] if i < len(row) else \\\"\\\" for i in indices]\",\"\",\"\",\"def rows_and_header(path, delim, nh):\",\"    rows = read_rows(path, delim)\",\"    if nh:\",\"        return [], rows, rows[0] if rows else []\",\"    return (rows[0] if rows else []), rows[1:], (rows[0] if rows else [])\",\"\",\"\",\"def run_headers(opts, positional):\",\"    delim = delimiter(opts.get(\\\"delimiter\\\", \\\",\\\"))\",\"    paths = positional or [None]\",\"    headers = []\",\"    for path in paths:\",\"        rows = read_rows(path, delim)\",\"        head = rows[0] if rows else []\",\"        for field in head:\",\"            if not opts.get(\\\"intersect\\\") or field not in headers:\",\"                headers.append(field)\",\"    just_names = bool(opts.get(\\\"just_names\\\")) or len(paths) > 1\",\"    if just_names:\",\"        write_bytes(b\\\"\\\".join(encode_text(field) + b\\\"\\\\n\\\" for field in headers))\",\"    else:\",\"        lines = [[str(i + 1), field] for i, field in enumerate(headers)]\",\"        write_bytes(aligned_bytes(lines, 2, 2))\",\"\",\"\",\"def run_count(opts, positional):\",\"