\",\"        start, end = index, index + 1\",\"    elif end is not None and length is not None:\",\"        raise XsvError(\\\"--end and --len cannot be used at the same time.\\\")\",\"    else:\",\"        start = start or 0\",\"        if end is not None and start > end:\",\"            raise XsvError(\",\"                \\\"The end of the range ({}) must be greater than or\\\\nequal to the start of the range ({}).\\\"\",\"                .format(end, start))\",\"        end = start + length if length is not None else end\",\"    part = records[start:end]\",\"    if opts.get(\\\"output\\\") is not None:\",\"        out.extend(part)\",\"        write_bytes(csv_bytes(out), opts.get(\\\"output\\\"))\",\"    else:\",\"        write_bytes(csv_bytes(part))\",\"\",\"\",\"def run_search(opts, positional):\",\"    if not positional or len(positional) > 2:\",\"        raise XsvError(\\\"Invalid arguments.\\\")\",\"    pattern_text = positional[0]\",\"    path = positional[1] if len(positional) == 2 else None\",\"    try:\",\"        pattern = re.compile(pattern_text, re.IGNORECASE if opts.get(\\\"ignore_case\\\") else 0)\",\"    except re.error as err:\",\"        raise XsvError(str(err))\",\"    nh = no_headers(opts)\",\"    header, records, first = rows_and_header(\",\"        path, delimiter(opts.get(\\\"delimiter\\\", \\\",\\\")), nh)\",\"    indices = select_indices(opts.get(\\\"select\\\", \\\"\\\"), first, not nh)\",\"    out = [] if nh or not header else [header]\",\"    for row in records:\",\"        match = any(pattern.search(field) is not None for field in selected(row, indices))\",\"        if bool(opts.get(\\\"invert_match\\\")) != match:\",\"            out.append(row)\",\"    write_bytes(csv_bytes(out), opts.get(\\\"output\\\"))\",\"\",\"\",\"def byte_key(value):\",\"    return encode_text(value)\",\"\",\"\",\"def compare_lex(left, right):\",\"    for a, b in zip(left, right):\",\"        aa, bb = byte_key(a), byte_key(b)\",\"        if aa < bb:\",\"            return -1\",\"        if aa > bb:\",\"            return 1\",\"    return (len(left) > len(right)) - (len(left) < len(right))\",\"\",\"\",\"def rust_number(value):\",\"    try:\",\"        if re.fullmatch(r\\\"[+-]?\\\\d+\\\", value):\",\"            number = int(value)\",\"            if -(2 ** 63) <= number < 2 ** 63:\",\"                return number\",\"        return float(value)\",\"    except ValueError:\",\"        return None\",\"\",\"\",\"def compare_numeric(left, right):\",\"    for a, b in zip(left, right):\",\"        aa, bb = rust_number(a), rust_number(b)\",\"        if aa is None and bb is None:\",\"            return 0\",\"        if aa is None:\",\"            return -1\",\"        if bb is None:\",\"            return 1\",\"        if isinstance(aa, float) and math.isnan(aa):\",\"            continue\",\"        if isinstance(bb, float) and math.isnan(bb):\",\"            continue\",\"        if aa < bb:\",\"            return -1\",\"        if aa > bb:\",\"            return 1\",\"    return (len(left) > len(right)) - (len(left) < len(right))\",\"\",\"\",\"def run_sort(opts, positional):\",\"    path = command_input(positional)\",\"    nh = no_headers(opts)\",\"    header, records, first = rows_and_header(\",\"        path, delimiter(opts.get(\\\"delimiter\\\", \\\",\\\")), nh)\",\"    indices = select_indices(opts.get(\\\"select\\\", \\\"\\\"), first, not nh)\",\"    comparator = compare_numeric if opts.get(\\\"numeric\\\") else compare_lex\",\"    def cmp_rows(a, b):\",\"        result = comparator(selected(a, indices), selected(b, indices))\",\"        return -result if opts.get(\\\"reverse\\\") else result\",\"    records.sort(key=functools.cmp_to_key(cmp_rows))\",\"    out = ([] if nh or not header else [header]) + records\",\"    write_bytes(csv_bytes(out), opts.get(\\\"output\\\"))\",\"\",\"\",\"def condense(value, limit):\",\"    if limit is None or len(value) <= limit:\",\"        return value\",\"    return value[:limit] + \\\"...\\\"\",\"\",\"\",\"def aligned_bytes(rows, minimum, padding):\",\"    if not rows:\",\"        return b\\\"\\\"\",\"    columns = max(len(row) for row in rows)\",\"    widths = []\",\"    for col in range(columns):\",\"        longest = max((len(encode_text(row[col])) if col < len(row) else 0)\",\"                      for row in rows)\",\"        widths.append(max(minimum, longest) + padding)\",\"    output = bytearray()\",\"    for row in rows:\",\"        for col, field in enumerate(row):\",\"            data = encode_text(field)\",\"            output.extend(data)\",\"            if col + 1 < len(row):\",\"                output.extend(b\\\" \\\" * max(0, widths[col] - len(data)))\",\"        output.extend(b\\\"\\\\n\\\")\",\"    return bytes(output)\",\"\",\"\",\"def run_table(opts, positional):\",\"    path = command_input(positional)\",\"    rows = read_rows(path, delimiter(opts.get(\\\"delimiter\\\", \\\",\\\")))\",\"    limit = as_nonnegative(opts[\\\"condense\\\"], \\\"condense\\\") if \\\"condense\\\" in opts else None\",\"    rows = [[condense(field, limit) for field in row] for row in rows]\",\"    width = as_nonnegative(opts.get(\\\"width\\\", \\\"2\\\"), \\\"width\\\")\",\"    pad = as_nonnegative(opts.get(\\\"pad\\\", \\\"2\\\"), \\\"pad\\\")\",\"    write_bytes(aligned_bytes(rows, width, pad), opts.get(\\\"output\\\"))\",\"\",\"\",\"def run_fmt(opts, positional):\",\"    path = command_input(positional)\",\"    rows = read_rows(path, delimiter(opts.get(\\\"delimiter\\\", \\\",\\\")))\",\"    out_delim = delimiter(opts.get(\\\"out_delimiter\\\", \\\",\\\"))\",\"    terminator = \\\"\\\\r\\\\n\\\" if opts.get(\\\"crlf\\\") else \\\"\\\\n\\\"\",\"    if opts.get(\\\"ascii\\\"):\",\"        out_delim, terminator = \\\"\\\\x1f\\\", \\\"\\\\x1e\\\"\",\"    quote = delimiter(opts.get(\\\"quote\\\", '\\\"'))\",\"    escape = delimiter(opts[\\\"escape\\\"]) if \\\"escape\\\" in opts else None\",\"    data = csv_bytes(rows, out_delim, terminator, quote,\",\"                     bool(opts.get(\\\"quote_always\\\")), escape, escape is None)\",\"    write_bytes(data, opts.get(\\\"output\\\"))\",\"\",\"\",\"def float_text(value):\",\"    if math.isnan(value):\",\"        return \\\"NaN\\\"\",\"    if math.isinf(value):\",\"        return \\\"inf\\\" if value > 0 else \\\"-inf\\\"\",\"    if value == 0:\",\"        return \\\"0\\\"\",\"    return repr(float(value))\",\"\",\"\",\"def field_type(values):\",\"    current = \\\"NULL\\\"\",\"    for value in values:\",\"        if value == \\\"\\\":\",\"            continue\",\"        try:\",\"            encode_text(value).decode(\\\"utf-8\\\")\",\"        except UnicodeDecodeError:\",\"            return \\\"Unknown\\\"\",\"        number = rust_number(value)\",\"        sample = \\\"Integer\\\" if number is not None and isinstance(number, int) else (\",\"            \\\"Float\\\" if number is not None else \\\"Unicode\\\")\",\"        if current == \\\"NULL\\\":\",\"            current = sample\",\"        elif current == \\\"Integer\\\" and sample == \\\"Float\\\":\",\"            current = \\\"Float\\\"\",\"        elif current == \\\"Float\\\" and sample == \\\"Integer\\\":\",\"            pass\",\"        elif current != sample:\",\"            current = \\\"Unicode\\\"\",\"    return current\",\"\",\"\",\"def numeric_values(values, include_nulls):\",\"    result = []\",\"    for value in values:\",\"        if value == \\\"\\\":\",\"            if include_nulls:\",\"                result.append(0.0)\",\"            continue\",\"        number = rust_number(value)\",\"        if number is not None:\",\"            result.append(float(number))\",\"    return result\",\"\",\"\",\"def minmax_for(values, typ):\",\"    nonnull = [value for value in values if value != \\\"\\\"]\",\"    if not nonnull:\",\"        return \\\"\\\", \\\"\\\"\",\"    if typ in (\\\"Integer\\\", \\\"Float\\\"):\",\"        pairs = [(rust_number(value), value) for value in nonnull]\",\"        pairs 